import os
import subprocess
import time

import taf.collectors.core as collectors_core
import taf.collectors.btslog as btslog

from typing import Optional, Union

from taf.collectors.core import ExecutionError
from taf.transport.ssh import ssh

from taf.rfrl.csv4all.resources.utilities.decorators import function_wrapper
from taf.rfrl.csv4all.resources.utilities.utilities import test_logger


class BtsLogCollector:
    def __init__(self, log_dir: str = "/tmp/btslog2", btslog_path: str = "/opt/btslog/btslog",
                 btslog_launcher_path: str = "/opt/btslog/btslog_launcher", syslog_timeout: int = 60):
        self.btslog_dir = f"{log_dir}/btslog"
        self.btslog_path = btslog_path
        self.btslog_launcher_path = btslog_launcher_path
        self._collector_names = set()
        self._collector_names_str = None
        self.ssh = ssh()
        self.target_file_name = ""
        self.config = {"LOG_CONFIGURATION": {
            "MaxTraceFileSize": "1",
            "MaxSysLogFileSize": "50",
            "SysLogFileTemplate": f"{self.btslog_dir}/SYSLOG_%1.LOG"}
        }
        self._btslog = btslog.btslog()
        self._core = collectors_core.CollectorKeywords()
        self.running = False
        self.syslog_timeout = syslog_timeout

    @function_wrapper
    def create_btslog(self, vm_details: dict = None, alias: Optional[str] = "default",
                      target_file_name: Optional[str] = "syslog_files.tgz") -> None:
        test_logger(f"btslog is running: {self.running}", "DEBUG")
        if not self.running:
            self.target_file_name = target_file_name
            self._clear_btslog_tempdir(vm_details)
            self._collector_names.add(alias)
            self._btslog.create_btslog_collector(
                name=alias,
                log_dir=self.btslog_dir,
                btslog_path=self.btslog_path,
                btslog_launcher_path=self.btslog_launcher_path,
                start_timeout=120,
                target_file_name=self.target_file_name,
                btslog_configuration=self.config,
                syslog_timeout=self.syslog_timeout,
                executor=vm_details)

    @function_wrapper
    def start_btslog(self) -> None:
        test_logger(f"btslog is running: {self.running}", "DEBUG")
        if not self.running:
            self._collector_names_str = ",".join(self._collector_names)
            test_logger("setup collectors...", "DEBUG")
            self._core.setup_collectors(names=self._collector_names_str)
            test_logger("start collectors...", "DEBUG")
            self._core.start_collectors(names=self._collector_names_str)
            self.running = True
            time.sleep(5)

    @function_wrapper
    def stop_btslog_and_download_logs(self, logs_dir) -> Union[list, None]:
        if self.running:
            try:
                if not os.path.exists(logs_dir):
                    os.makedirs(logs_dir, exist_ok=True)

                test_logger("stopping collectors...", "DEBUG")
                self._core.stop_collectors(names=self._collector_names_str)
                test_logger("collecting collectors...", "DEBUG")
                self._core.collect_collectors(names=self._collector_names_str, target_dir=logs_dir)
                test_logger("tearing down collectors...", "DEBUG")
                self._core.teardown_collectors(names=self._collector_names_str)
                self.running = False
                collector_names = [f"{logs_dir}/{collector_name}/{self.target_file_name}"
                                   for collector_name in self._collector_names]
                test_logger("clearing names...", "DEBUG")
                self._collector_names.clear()
                return collector_names
            except ExecutionError as e:
                test_logger(e, "DEBUG")
                self._core.teardown_collectors(names=self._collector_names_str)
                self._collector_names.clear()
                raise
        return None

    def _clear_btslog_tempdir(self, vm_details: dict) -> None:
        test_logger(f"clearing {self.btslog_dir} ...", "DEBUG")
        cmd = f"rm -rf {self.btslog_dir}/*"
        if vm_details:
            self.ssh.connect_to(hostname=vm_details.get("host"), username=vm_details.get("user"),
                                password=vm_details.get("password"), alias=f"btslog_{vm_details.get('host')}")
            self.ssh.execute(cmd, connection=f"btslog_{vm_details.get('host')}")
            self.ssh.disconnect(connection=f"btslog_{vm_details.get('host')}")
        else:
            try:
                subprocess.run(cmd, shell=True, check=True, capture_output=True, text=True, timeout=60)
            except subprocess.CalledProcessError as e:
                test_logger(f"Removing directory {self.btslog_dir} failed:\n {e}", "WARN")
                test_logger(f"stderr: {e.stderr}", "DEBUG")
            except Exception as e:
                test_logger(f"Unexpected error:\n {e}", "DEBUG")
